"""Generate the static deep-space nebula layer used by the Love canvas scene."""
from pathlib import Path

SVG = """<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1600" preserveAspectRatio="xMidYMid slice"><defs><radialGradient id="a"><stop stop-color="#087cff" stop-opacity=".3"/><stop offset=".5" stop-color="#0649a8" stop-opacity=".13"/><stop offset="1" stop-color="#01030b" stop-opacity="0"/></radialGradient><radialGradient id="b"><stop stop-color="#00c8ff" stop-opacity=".22"/><stop offset=".5" stop-color="#063c8a" stop-opacity=".1"/><stop offset="1" stop-color="#01030b" stop-opacity="0"/></radialGradient><filter id="blur"><feGaussianBlur stdDeviation="42"/></filter></defs><rect width="900" height="1600" fill="#01030b"/><g filter="url(#blur)"><ellipse cx="190" cy="520" rx="330" ry="220" fill="url(#a)" transform="rotate(-28 190 520)"/><ellipse cx="730" cy="940" rx="360" ry="260" fill="url(#b)" transform="rotate(32 730 940)"/><ellipse cx="410" cy="1240" rx="320" ry="190" fill="url(#a)"/><ellipse cx="680" cy="280" rx="280" ry="190" fill="url(#b)"/></g><g fill="none" stroke="#3aaeff" stroke-opacity=".12" stroke-width="2"><path d="M-80 700 C170 480 280 900 520 680 S850 480 1000 620"/><path d="M-80 1120 C160 920 330 1250 560 1060 S820 930 1000 1080"/></g></svg>"""

Path(__file__).resolve().parents[1].joinpath("nebula.svg").write_text(SVG, encoding="utf-8")
print("Generated nebula.svg")
